import sys, json
data = sys.stdin.read()
lines = data.strip().split('\n')
for line in lines[-8:]:
    try:
        obj = json.loads(line)
        tp = obj.get('type','?')
        if tp == 'assistant':
            content = obj.get('message',{}).get('content',[])
            for block in content:
                if block.get('type') == 'text':
                    print(f'[AST] {block[\"text\"][:400]}')
                elif block.get('type') == 'tool_use':
                    name = block.get('name','?')
                    inp = str(block.get('input',{}))[:200]
                    print(f'[TOOL] {name}: {inp}')
        elif tp == 'user':
            content = obj.get('message',{}).get('content',[])
            for block in content:
                if isinstance(block, dict) and block.get('type') == 'tool_result':
                    c = str(block.get('content',''))[:200]
                    print(f'[RESULT] {c}')
        elif tp in ('rate_limit_event', 'system'):
            print(f'[{tp}]')
    except Exception as e:
        pass
" 2>/dev/null
